using System;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;

public class Program
{
    public static void Main()
    {
        // PROGRAM: Menginspeksi Negosiasi Versi Protokol HTTP di .NET
        var request = new HttpRequestMessage(HttpMethod.Get, "https://api.enterprise.internal")
        {
            Version = HttpVersion.Version20,
            VersionPolicy = HttpVersionPolicy.RequestVersionOrHigher
        };

        Console.WriteLine($"Target URI: {request.RequestUri}");
        Console.WriteLine($"Diminta Versi: HTTP/{request.Version}");
        Console.WriteLine($"Version Policy: {request.VersionPolicy}");

        // Simulasi respon server yang mendukung HTTP/2
        var response = new HttpResponseMessage(HttpStatusCode.OK)
        {
            Version = HttpVersion.Version20
        };

        Console.WriteLine($"\nStatus Code: {response.StatusCode}");
        Console.WriteLine($"Versi Protokol HTTP yang Dinegosiasikan: HTTP/{response.Version}");

        if (response.Version.Major >= 2)
        {
            Console.WriteLine("Sukses! Koneksi menggunakan Multiplexed Binary Framing modern.");
        }
    }
}

