using System;

public class HttpVersionInspector
{
    public static string GetProtocolFeatures(string httpVersion)
    {
        if (string.IsNullOrWhiteSpace(httpVersion)) return "Unknown-Version";

        return httpVersion.Trim() switch
        {
            "1.1" => "Text-Based;Sequential",
            "2.0" or "2" => "Binary-Framing;Multiplexing;HPACK",
            "3.0" or "3" => "QUIC-UDP;Independent-Streams;Zero-HOL",
            _ => "Unknown-Version"
        };
    }

    public static void Main()
    {
        Console.WriteLine(GetProtocolFeatures("2.0"));
        Console.WriteLine(GetProtocolFeatures("3"));
    }
}
